import json
import numpy as np
import pandas as pd
import stan

# ---------------------------------------------------------------------------
# 1. Read the same data files as the R script
# ---------------------------------------------------------------------------
with open("/app/meta_public.json") as f:
    meta_pub = json.load(f)

train_X = pd.read_csv("/app/train_X.csv").to_numpy()   # (N, D)
test_X  = pd.read_csv("/app/test_X.csv").to_numpy()    # (N_new, D)
train_y = pd.read_csv("/app/train_y.csv")["y"].to_numpy()  # (N,)

P = int(meta_pub["P"])
jitter = float(meta_pub["jitter"])

N = train_X.shape[0]
D = train_X.shape[1]
N_new = test_X.shape[0]

# H = cbind(1, X[,1], X[,2])  (1-indexed in R -> columns 0 and 1 in python)
H = np.column_stack([np.ones(N), train_X[:, 0], train_X[:, 1]])
if N_new > 0:
    H_new = np.column_stack([np.ones(N_new), test_X[:, 0], test_X[:, 1]])
    X_new = test_X
else:
    H_new = np.zeros((0, P))
    X_new = np.zeros((0, D))

